$escape = static fn($v) => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
$manageUrl = Yii::$app->urlManager->createUrl(['app-hub/manage']);
$iconPreview = static function (array $app) use ($escape): string {
    $icon = trim((string)($app['icon'] ?? '🧩'));
    $parts = parse_url($icon);
    if (is_array($parts) && strtolower((string)($parts['scheme'] ?? '')) === 'https' && !empty($parts['host'])) return '<img src="' . $escape($icon) . '" alt="" loading="lazy">';
    return $escape($icon);
};
